// Computer Use: an agent drives a GUI it can only perceive as screenshots.
// Each cycle it takes a screenshot (a text grid of labeled elements), grounds
// an intent to pixel coordinates, clicks, then observes whether the screen
// changed as expected, recovering from an unexpected consent popup.

#[derive(Clone)]
struct Element {
    label: String,
    col: i32,
    row: i32,
}

struct Screenshot {
    screen: String,
    popup: bool,
    elements: Vec<Element>,
}

struct Desktop {
    screen: String,
    popup_open: bool,
    dark_mode: bool,
}

fn el(label: &str, col: i32, row: i32) -> Element {
    Element { label: label.to_string(), col, row }
}

impl Desktop {
    fn new() -> Self {
        Desktop { screen: "home".to_string(), popup_open: true, dark_mode: false }
    }

    fn screenshot(&self) -> Screenshot {
        if self.popup_open {
            return Screenshot {
                screen: self.screen.clone(),
                popup: true,
                elements: vec![el("Consent: Accept", 1, 1), el("Consent: Decline", 2, 1)],
            };
        }
        if self.screen == "home" {
            return Screenshot { screen: "home".to_string(), popup: false,
                elements: vec![el("Settings", 0, 2), el("Profile", 2, 2)] };
        }
        if self.screen == "settings" {
            return Screenshot { screen: "settings".to_string(), popup: false,
                elements: vec![el("General", 0, 1), el("Appearance", 1, 1)] };
        }
        let label = if self.dark_mode { "Dark Mode: ON" } else { "Dark Mode: OFF" };
        Screenshot { screen: "appearance".to_string(), popup: false, elements: vec![el(label, 1, 1)] }
    }

    // A click lands at pixel coords; the element nearest those pixels reacts.
    fn click_at(&mut self, x: i32, y: i32, shot: &Screenshot) {
        if let Some(hit) = nearest(&shot.elements, x, y) {
            if hit.label.starts_with("Consent:") {
                self.popup_open = false;
            } else if hit.label == "Settings" {
                self.screen = "settings".to_string();
            } else if hit.label == "Appearance" {
                self.screen = "appearance".to_string();
            } else if hit.label.starts_with("Dark Mode") {
                self.dark_mode = !self.dark_mode;
            }
        }
    }
}

fn px(e: &Element) -> (i32, i32) {
    (e.col * 100 + 50, e.row * 60 + 30)
}

fn nearest<'a>(els: &'a [Element], x: i32, y: i32) -> Option<&'a Element> {
    let mut best: Option<&Element> = None;
    let mut best_d = i32::MAX;
    for e in els {
        let (ex, ey) = px(e);
        let d = (ex - x).abs() + (ey - y).abs();
        if d < best_d {
            best_d = d;
            best = Some(e);
        }
    }
    best
}

fn ground(shot: &Screenshot, want: &str) -> Option<(i32, i32)> {
    for e in &shot.elements {
        if e.label == want {
            return Some(px(e));
        }
    }
    None
}

fn render_grid(shot: &Screenshot) -> String {
    let mut lines: Vec<String> = Vec::new();
    for r in 0..4 {
        let mut parts: Vec<String> = Vec::new();
        for c in 0..3 {
            let mut text = String::from(".");
            for e in &shot.elements {
                if e.col == c && e.row == r {
                    text = e.label.clone();
                }
            }
            while text.chars().count() < 18 {
                text.push(' ');
            }
            let cell: String = text.chars().take(18).collect();
            parts.push(cell);
        }
        let joined = parts.join("|");
        let stripped: String = joined.chars().filter(|c| *c != '.' && *c != '|' && *c != ' ').collect();
        if !stripped.is_empty() {
            lines.push(format!("    {}", joined));
        }
    }
    lines.join("\n")
}

// Model stub: pick the next action purely from what the screenshot shows.
fn decide(shot: &Screenshot) -> (String, String) {
    if shot.popup {
        return ("click".to_string(), "Consent: Accept".to_string());
    }
    if shot.screen == "home" {
        return ("click".to_string(), "Settings".to_string());
    }
    if shot.screen == "settings" {
        return ("click".to_string(), "Appearance".to_string());
    }
    if !shot.elements.is_empty() && shot.elements[0].label == "Dark Mode: OFF" {
        return ("click".to_string(), "Dark Mode: OFF".to_string());
    }
    ("done".to_string(), String::new())
}

fn snapshot_string(d: &Desktop) -> String {
    format!("{}|{}|{}", d.screen, d.popup_open, d.dark_mode)
}

fn main() {
    let mut desk = Desktop::new();
    println!("Task: enable dark mode in the Settings app (screenshots + clicks only)\n");
    for cycle in 1..=8 {
        let shot = desk.screenshot();
        println!("--- cycle {} ---", cycle);
        println!("[screenshot] screen={} popup={}", shot.screen, if shot.popup { "OPEN" } else { "none" });
        println!("{}", render_grid(&shot));
        let (action, label) = decide(&shot);
        if action == "done" {
            println!("[reason] dark mode is ON; goal reached, stopping.\n");
            println!("Result: dark mode enabled with no API, only screenshot -> ground -> click -> observe.");
            return;
        }
        let reason = if shot.popup {
            "a consent popup is blocking the UI; dismiss it before continuing".to_string()
        } else {
            format!("advance toward the Dark Mode toggle by clicking \"{}\"", label)
        };
        println!("[reason] {}", reason);
        match ground(&shot, &label) {
            None => {
                println!("[ground] target not found, retry");
                continue;
            }
            Some((x, y)) => {
                println!("[ground] \"{}\" -> pixel ({},{})", label, x, y);
                let before = snapshot_string(&desk);
                desk.click_at(x, y, &shot);
                let after = snapshot_string(&desk);
                println!("[act] click ({},{})", x, y);
                println!("[observe] screen changed: {}\n", if before != after { "yes" } else { "no" });
            }
        }
    }
    println!("Result: stopped after max cycles.");
}

